import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public final class UndirectedGraph implements Graph {
    private final List<List<Integer>> adjacencyList;

    private UndirectedGraph(List<List<Integer>> adjacencyList) {
        this.adjacencyList = adjacencyList;
    }

    public static UndirectedGraph withVertexCount(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }

        List<List<Integer>> adjacencyList = new ArrayList<>(vertexCount);
        for (int vertex = 0; vertex < vertexCount; vertex++) {
            adjacencyList.add(new ArrayList<>());
        }
        return new UndirectedGraph(adjacencyList);
    }

    public static UndirectedGraph fromAdjacencyList(List<? extends List<Integer>> source) {
        if (source == null) {
            throw new IllegalArgumentException("adjacencyList cannot be null");
        }

        List<List<Integer>> adjacencyList = new ArrayList<>(source.size());
        for (int vertex = 0; vertex < source.size(); vertex++) {
            adjacencyList.add(copyAndValidateNeighbors(source, vertex));
        }

        return new UndirectedGraph(adjacencyList);
    }

    @Override
    public int vertexCount() {
        return adjacencyList.size();
    }

    @Override
    public List<Integer> neighbors(int vertex) {
        validateVertex(vertexCount(), vertex);
        return Collections.unmodifiableList(adjacencyList.get(vertex));
    }

    public void addEdge(int firstVertex, int secondVertex) {
        validateVertex(vertexCount(), firstVertex);
        validateVertex(vertexCount(), secondVertex);

        adjacencyList.get(firstVertex).add(secondVertex);
        adjacencyList.get(secondVertex).add(firstVertex);
    }

    private static List<Integer> copyAndValidateNeighbors(List<? extends List<Integer>> source, int vertex) {
        List<Integer> neighbors = source.get(vertex);
        if (neighbors == null) {
            throw new IllegalArgumentException("adjacency list cannot be null for vertex " + vertex);
        }

        List<Integer> copiedNeighbors = new ArrayList<>(neighbors.size());
        for (Integer neighbor : neighbors) {
            validateVertex(source.size(), neighbor);
            copiedNeighbors.add(neighbor);
        }
        return copiedNeighbors;
    }

    private static void validateVertex(int vertexCount, Integer vertex) {
        if (vertex == null) {
            throw new IllegalArgumentException("vertex cannot be null");
        }
        if (vertex < 0 || vertex >= vertexCount) {
            throw new IllegalArgumentException("vertex out of range: " + vertex);
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public final class ConnectedComponentsTest {

    private ConnectedComponentsTest() {
    }

    public static void main(String[] args) {
        findsComponentsInSampleGraph();
        keepsLegacyGetComponentsApi();
        worksWithGraphInterface();
        handlesIsolatedVertices();
        returnsReadOnlyComponents();
        copiesAdjacencyListsDefensively();
        rejectsInvalidEdges();
        exposesReadOnlyNeighbors();
    }

    private static void returnsReadOnlyComponents() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(2);
        graph.addEdge(0, 1);
        List<List<Integer>> components = ConnectedComponents.findComponents(graph);

        assertThrows(
                UnsupportedOperationException.class,
                () -> components.add(List.of(2)),
                "read-only component list"
        );
        assertThrows(
                UnsupportedOperationException.class,
                () -> components.get(0).add(2),
                "read-only component"
        );
    }

    @SuppressWarnings("deprecation")
    private static void keepsLegacyGetComponentsApi() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(2);
        graph.addEdge(0, 1);

        assertEquals(
                List.of(List.of(0, 1)),
                ConnectedComponents.getComponents(graph),
                "legacy getComponents API"
        );
    }

    private static void findsComponentsInSampleGraph() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(6);
        graph.addEdge(1, 2);
        graph.addEdge(0, 3);
        graph.addEdge(2, 0);
        graph.addEdge(5, 4);

        assertEquals(
                List.of(List.of(0, 3, 2, 1), List.of(4, 5)),
                ConnectedComponents.findComponents(graph),
                "sample graph components"
        );
    }

    private static void worksWithGraphInterface() {
        Graph graph = new StaticGraph(List.of(
                List.of(1),
                List.of(0),
                List.of()
        ));

        assertEquals(
                List.of(List.of(0, 1), List.of(2)),
                ConnectedComponents.findComponents(graph),
                "graph interface"
        );
    }

    private static void handlesIsolatedVertices() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(3);

        assertEquals(
                List.of(List.of(0), List.of(1), List.of(2)),
                ConnectedComponents.findComponents(graph),
                "isolated vertices"
        );
    }

    private static void copiesAdjacencyListsDefensively() {
        List<List<Integer>> source = new ArrayList<>();
        source.add(new ArrayList<>(List.of(1)));
        source.add(new ArrayList<>(List.of(0)));

        UndirectedGraph graph = UndirectedGraph.fromAdjacencyList(source);
        source.get(0).clear();

        assertEquals(List.of(1), graph.neighbors(0), "defensive adjacency copy");
    }

    private static void rejectsInvalidEdges() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(2);

        assertThrows(
                IllegalArgumentException.class,
                () -> graph.addEdge(0, 2),
                "invalid edge"
        );
    }

    private static void exposesReadOnlyNeighbors() {
        UndirectedGraph graph = UndirectedGraph.withVertexCount(2);
        graph.addEdge(0, 1);

        assertThrows(
                UnsupportedOperationException.class,
                () -> graph.neighbors(0).add(1),
                "read-only neighbors"
        );
    }

    private static void assertEquals(Object expected, Object actual, String label) {
        if (!expected.equals(actual)) {
            throw new AssertionError(label + " expected <" + expected + "> but was <" + actual + ">");
        }
    }

    private static void assertThrows(
            Class<? extends RuntimeException> expectedType,
            Runnable action,
            String label
    ) {
        try {
            action.run();
        } catch (RuntimeException exception) {
            if (expectedType.isInstance(exception)) {
                return;
            }
            throw new AssertionError(label + " threw unexpected exception " + exception, exception);
        }

        throw new AssertionError(label + " did not throw " + expectedType.getSimpleName());
    }

    private static final class StaticGraph implements Graph {
        private final List<List<Integer>> adjacencyList;

        private StaticGraph(List<List<Integer>> adjacencyList) {
            this.adjacencyList = adjacencyList;
        }

        @Override
        public int vertexCount() {
            return adjacencyList.size();
        }

        @Override
        public Iterable<Integer> neighbors(int vertex) {
            return adjacencyList.get(vertex);
        }
    }
}

